#include<bits/stdc++.h>
using namespace std;
bool tree[10002];
int main(){
	int m,l,sum=0;
	scanf("%d%d",&l,&m);
	for(int i=0;i<m;i++){
		int le,ri;
		scanf("%d%d",&le,&ri);
		for(int i=le;i<=ri;i++){
			if(tree[i]==0){
				sum++;
				tree[i]=1;
			}
		}
	}
	printf("%d",l+1-sum);
	return 0;
}
